# Public integration tests for D52 pure actual-change imputation
# (`selection_est_method = "imputation"`) through cdid::att_gt()/aggte().
#
# These are request-gate, wiring, metadata, invariance and exact-identity
# checks on a deterministic finite fixture. They are labelled self-consistency
# checks: no expected value is generated by fit_imputation_backend() or by the
# test-only dense diagnostics. Acceptance of point/IF/covariance values against
# the independent company public reference is supplied separately by root.

impp_has_installed_cdid <- function() {
  isNamespaceLoaded("cdid") || requireNamespace("cdid", quietly = TRUE)
}

impp_val <- function(name) {
  ns <- asNamespace("cdid")
  stopifnot(isNamespace(ns), environmentIsLocked(ns), bindingIsLocked(name, ns))
  get(name, envir = ns, inherits = FALSE)
}

impp_poolings <- c("separate", "within_cohort", "across_cohorts")
impp_methods <- c("ipw", "reg", "dr")

# Deterministic panel: dates 1:5, cohorts 0 (never treated), 3, 4, 5; binary x,
# continuous z; every ordered pair is observed in every cohort; singleton and
# zero-observation units; all but one zero-observation unit are frame-only.
impp_fixture <- function(balanced = FALSE, reps = 2L) {
  dates <- 1:5
  cohorts <- c(0, 3, 4, 5)
  patterns <- if (balanced) list(1:5) else list(1:5, c(1, 2), c(2, 3), c(3, 4), c(4, 5), c(1, 3), c(2, 4),
    c(3, 5), c(1, 4), c(2, 5), c(1, 5), c(1, 2, 4), 3L, integer(0))
  grid <- expand.grid(rep = seq_len(reps), pattern = seq_along(patterns), x = 0:1, g = cohorts,
    KEEP.OUT.ATTRS = FALSE)
  N <- nrow(grid)
  k <- seq_len(N)
  ids <- sprintf("u%03d", k)
  z <- ((k * 37) %% 101) / 50 - 1
  w <- 0.5 + ((k * 13) %% 7) / 4
  cl <- paste0("c", (k - 1L) %/% 4L)
  theta <- c(`3` = 1, `4` = 2, `5` = 1.5)
  y_at <- function(i, t) {
    g <- grid$g[i]; x <- grid$x[i]
    effect <- if (g > 0 && t >= g) theta[[as.character(g)]] + 0.5 * (t - g) + 1 * x else 0
    0.3 * z[i] + 0.1 * match(g, cohorts) + 0.2 * t + 0.5 * x * (t - 1) + effect + 0.25 * sin(3.1 * i + 1.3 * t)
  }
  long <- do.call(rbind, lapply(k, function(i) {
    obs <- dates %in% patterns[[grid$pattern[i]]]
    data.frame(id = ids[i], time = dates,
      y = ifelse(obs, vapply(dates, function(t) y_at(i, t), numeric(1)), NA_real_),
      g = grid$g[i], x = grid$x[i], z = z[i], w = w[i], cl = cl[i], stringsAsFactors = FALSE)
  }))
  n_obs <- vapply(k, function(i) length(patterns[[grid$pattern[i]]]), integer(1))
  zero <- which(n_obs == 0L)
  frame_only <- ids[zero[-1L]]
  data <- long[!long$id %in% frame_only, , drop = FALSE]
  rownames(data) <- NULL
  frame <- data.frame(id = ids, g = grid$g, x = grid$x, z = z, w = w, cl = cl, stringsAsFactors = FALSE)
  list(data = data, frame = frame, n_obs = stats::setNames(n_obs, ids), frame_only = frame_only,
    off_A = ids[n_obs < 2L])
}

impp_args <- function(fx, ...) {
  args <- list(yname = "y", tname = "time", idname = "id", gname = "g", data = fx$data, frame = fx$frame,
    xformla = ~x + z, weightsname = "w", est_method = "dr", control_group = "nevertreated",
    bstrap = FALSE, cband = FALSE, gmm_weighting = "identity")
  utils::modifyList(args, list(...))
}

impp_fit <- function(fx, ...) do.call(cdid::att_gt, impp_args(fx, ...))

# Inactive probability-model arguments are passed as sentinels that error if forced.
impp_imputation <- function(fx, est_method, pooling = "separate", ...) {
  impp_fit(fx, est_method = est_method, selection = "conditional_mtar", selection_est_method = "imputation",
    imputation_pooling = pooling,
    selection_model = quote(stop("inactive selection_model was evaluated")),
    selection_pooling = quote(stop("inactive selection_pooling was evaluated")),
    selection_xformla = quote(stop("inactive selection_xformla was evaluated")), ...)
}

impp_refuse <- function(cls, ..., entry = cdid::att_gt) {
  base <- list(yname = "y", tname = "time", idname = "id", gname = "g",
    data = quote(stop("data must not be evaluated")))
  e <- testthat::expect_error(do.call(entry, utils::modifyList(base, list(...))), class = cls[[1L]])
  for (k in cls[-1L]) testthat::expect_s3_class(e, k)
  testthat::expect_no_match(conditionMessage(e), "must not be evaluated|was evaluated")
  invisible(e)
}

# ------------------------------------------------------------------------------
# A. Public surface, lazy forwarding and request gates (before any data)
# ------------------------------------------------------------------------------

testthat::test_that("att_gt adds selection_est_method and imputation_pooling as chained-only formals", {
  testthat::skip_if_not(impp_has_installed_cdid(), "Installed cdid namespace required.")
  f <- formals(cdid::att_gt)
  up <- impp_val("upstream_att_gt_formals")
  ch <- impp_val("cdid_chained_only_formals")
  n_up <- length(up)
  testthat::expect_identical(names(f)[seq_len(n_up)], up)
  testthat::expect_identical(names(f)[n_up + 1L], "...")
  testthat::expect_identical(names(f)[-seq_len(n_up + 1L)], ch)
  testthat::expect_false(any(c("selection_est_method", "imputation_pooling") %in% up))
  pos <- match(c("selection_justification", "selection_est_method", "imputation_pooling", "gmm_weighting"), names(f))
  testthat::expect_identical(diff(pos), c(1L, 1L, 1L))
  testthat::expect_identical(f$selection_est_method, "ipw")
  testthat::expect_identical(f$imputation_pooling, "separate")
  testthat::expect_identical(f$est_method, "dr")
  testthat::expect_identical(f$selection, "none")
  testthat::expect_identical(names(f)[length(f)], "control")
})

testthat::test_that("ordinary mode neither evaluates nor forwards either new chained-only argument", {
  testthat::skip_if_not(impp_has_installed_cdid(), "Installed cdid namespace required.")
  d <- parity_panel()
  res <- cdid::att_gt(yname = "y", tname = "period", idname = "id", gname = "G", data = d, bstrap = FALSE,
    mode = "ordinary", selection_est_method = stop("selection_est_method must not be evaluated"),
    imputation_pooling = stop("imputation_pooling must not be evaluated"))
  ref <- did::att_gt(yname = "y", tname = "period", idname = "id", gname = "G", data = d, bstrap = FALSE)
  testthat::expect_s3_class(res, "MP")
  testthat::expect_false(inherits(res, "cdid_MP"))
  testthat::expect_identical(res$att, ref$att)
  testthat::expect_identical(res$se, ref$se)
  testthat::expect_identical(res$inffunc, ref$inffunc)
  testthat::expect_identical(names(as.list(res$DIDparams$call))[-1L],
    c("yname", "tname", "idname", "gname", "data", "bstrap"))
})

testthat::test_that("selection_est_method and imputation gates refuse unsupported requests before the data promise", {
  testthat::skip_if_not(impp_has_installed_cdid(), "Installed cdid namespace required.")
  uns <- "cdid_chained_request_unsupported_selection"
  # The augmented observation correction (D52 seventh route) is implemented with
  # est_method = "dr" only (test-chained-augmented-public.R); it stays explicitly
  # unavailable with treatment IPW/reg and still requires conditional_mtar.
  for (m in setdiff(impp_methods, "dr")) {
    e <- impp_refuse(c("cdid_chained_unavailable", uns), est_method = m, selection = "conditional_mtar",
      selection_est_method = "dr", imputation_pooling = quote(stop("imputation_pooling was evaluated")))
    testthat::expect_match(conditionMessage(e), "not implemented", fixed = TRUE)
  }
  e <- impp_refuse(uns, selection_est_method = "dr")
  testthat::expect_match(conditionMessage(e), "conditional_mtar", fixed = TRUE)
  for (bad in list("IPW", "imputed", "", NA_character_, c("ipw", "imputation"), 1)) impp_refuse(uns, selection_est_method = bad)
  # Pure imputation requires the conditional_mtar assumption on the representative F roster.
  e <- impp_refuse(uns, selection_est_method = "imputation",
    selection_model = quote(stop("inactive selection_model was evaluated")))
  testthat::expect_match(conditionMessage(e), "conditional_mtar", fixed = TRUE)
  for (u in c("B", "A")) impp_refuse(c(uns, "cdid_cp04_unsupported_error"), selection = "conditional_mtar",
    selection_est_method = "imputation", selection_universe = u, selection_justification = "declared representativeness")
  impp_refuse("cdid_chained_request_input_error", selection = "conditional_mtar", selection_est_method = "imputation",
    selection_rho = "rho")
  impp_refuse(uns, est_method = function(...) NULL, selection = "conditional_mtar", selection_est_method = "imputation",
    selection_xformla = quote(stop("inactive selection_xformla was evaluated")))
  for (bad in list("pooled", "global", "", NA_character_, c("separate", "within_cohort"), 1L))
    impp_refuse(uns, selection = "conditional_mtar", selection_est_method = "imputation", imputation_pooling = bad)
  # est_method keeps its own refusal ahead of the new axis.
  impp_refuse(c("cdid_chained_request_est_method", "cdid_chained_unavailable"), est_method = "stdipw",
    selection_est_method = "imputation")
})

testthat::test_that("gates pass without forcing inactive promises and reach the data", {
  testthat::skip_if_not(impp_has_installed_cdid(), "Installed cdid namespace required.")
  base <- list(yname = "y", tname = "time", idname = "id", gname = "g",
    data = quote(stop("data must not be evaluated")))
  reach <- function(...) testthat::expect_error(do.call(cdid::att_gt, c(base, list(...))), "data must not be evaluated")
  for (m in impp_methods) for (p in impp_poolings) {
    reach(est_method = m, selection = "conditional_mtar", selection_est_method = "imputation", imputation_pooling = p,
      selection_model = quote(stop("inactive selection_model was evaluated")),
      selection_pooling = quote(stop("inactive selection_pooling was evaluated")),
      selection_xformla = quote(stop("inactive selection_xformla was evaluated")))
  }
  reach(est_method = "dr", selection = "corollary1", selection_est_method = "imputation",
    selection_justification = "supplied representative roster")
  # Existing probability-weighted routes never evaluate imputation_pooling.
  for (m in impp_methods) {
    reach(est_method = m, imputation_pooling = quote(stop("imputation_pooling was evaluated")))
    reach(est_method = m, selection = "conditional_mtar", selection_est_method = "ipw",
      imputation_pooling = quote(stop("imputation_pooling was evaluated")))
  }
  # Development entry: the same gate runs before its explicit-control requirement.
  dev <- impp_val("chained_att_gt_request")
  impp_refuse(c("cdid_chained_unavailable", "cdid_chained_request_unsupported_selection"), entry = dev,
    est_method = "ipw", selection = "conditional_mtar", selection_est_method = "dr")
  impp_refuse("cdid_chained_request_control_error", entry = dev, est_method = "reg", selection = "conditional_mtar",
    selection_est_method = "imputation", selection_model = quote(stop("inactive selection_model was evaluated")))
})

# ------------------------------------------------------------------------------
# B. Unchanged probability-weighted defaults
# ------------------------------------------------------------------------------

testthat::test_that("default selection_est_method = 'ipw' is identical to explicit 'ipw' with an unforced pooling promise", {
  testthat::skip_if_not(impp_has_installed_cdid(), "Installed cdid namespace required.")
  fx <- impp_fixture()
  cases <- c(lapply(impp_methods, function(m) list(est_method = m)),
    list(list(est_method = "dr", selection = "conditional_mtar", selection_xformla = ~x)))
  for (cs in cases) {
    args <- do.call(impp_args, c(list(fx), cs, list(gmm_weighting = NULL)))
    fit_def <- do.call(cdid::att_gt, args)
    fit_exp <- do.call(cdid::att_gt, c(args, list(selection_est_method = "ipw",
      imputation_pooling = quote(stop("imputation_pooling must not be evaluated")))))
    for (nm in c("att", "se", "c", "V_analytical", "inffunc", "n")) testthat::expect_identical(fit_exp[[nm]], fit_def[[nm]])
    testthat::expect_identical(fit_exp$chained$estimator, fit_def$chained$estimator)
    testthat::expect_false(grepl("imputation", fit_exp$chained$estimator, fixed = TRUE))
    testthat::expect_identical(fit_exp$chained$selection, fit_def$chained$selection)
    testthat::expect_identical(fit_exp$chained$request$selection_est_method, "ipw")
    testthat::expect_null(fit_exp$chained$request$imputation_pooling)
    testthat::expect_identical(fit_exp$chained$request$inactive_arguments, "imputation_pooling")
    testthat::expect_false(identical(fit_exp$chained$selection$method, "imputation"))
  }
})

# ------------------------------------------------------------------------------
# C. Pure imputation through the existing consumers
# ------------------------------------------------------------------------------

impp_state <- new.env(parent = emptyenv())

testthat::test_that("pure imputation runs for every treatment method and pooling with accurate metadata", {
  testthat::skip_if_not(impp_has_installed_cdid(), "Installed cdid namespace required.")
  fx <- impp_fixture()
  N <- nrow(fx$frame)
  label <- impp_val("chained_result_estimator")
  for (m in impp_methods) for (p in impp_poolings) {
    fit <- impp_imputation(fx, m, p)
    assign(paste(m, p, sep = ":"), fit, envir = impp_state)
    testthat::expect_s3_class(fit, "cdid_MP")
    testthat::expect_identical(fit$DIDparams$est_method, m)
    testthat::expect_identical(fit$chained$estimator, label(m, "imputation"))
    testthat::expect_match(fit$chained$estimator, "(pure actual-change imputation)", fixed = TRUE)
    # Both method axes and the inactive probability arguments.
    req <- fit$chained$request
    testthat::expect_identical(req$selection_est_method, "imputation")
    testthat::expect_identical(req$imputation_pooling, p)
    testthat::expect_identical(req$est_method, m)
    testthat::expect_null(req$selection_model); testthat::expect_null(req$selection_pooling)
    testthat::expect_identical(req$inactive_arguments, c("selection_model", "selection_pooling", "selection_xformla"))
    sel <- fit$chained$selection
    testthat::expect_identical(sel$method, "imputation")
    testthat::expect_identical(sel$canonical_assumption, "conditional_mtar")
    testthat::expect_identical(c(sel$est_method, sel$imputation_pooling, sel$fitting_universe), c(m, p, "F"))
    testthat::expect_identical(sel$inactive_arguments, c("selection_model", "selection_pooling", "selection_xformla"))
    testthat::expect_equal(sel$models$n_selection_fits, 0)
    testthat::expect_equal(sel$models$observation_logit_models, 0)
    # Full-roster support, design source and the absence of probability fitting.
    nd <- fit$chained$nuisance_diagnostics
    testthat::expect_identical(nd$method, "imputation")
    testthat::expect_identical(c(nd$est_method, nd$imputation_pooling), c(m, p))
    testthat::expect_identical(nd$support$design_source, "X_frame")
    testthat::expect_identical(nd$support$design_columns, c("(Intercept)", "x", "z"))
    testthat::expect_equal(nd$support$design_rows, N)
    testthat::expect_equal(nd$support$n_full_frame_units, N)
    testthat::expect_equal(nd$support$observation_probability_models, 0)
    testthat::expect_false(nd$support$observation_probabilities_fitted)
    testthat::expect_gt(nd$accounting$design_owned_entries, 0)
    testthat::expect_equal(nd$accounting$design_borrowed_entries, 0)
    testthat::expect_equal(nd$accounting$observation_logit_models, 0)
    testthat::expect_equal(nd$accounting$n_selection_fits, 0)
    testthat::expect_true(nd$accounting$automatic_chunk_rows)
    testthat::expect_false(nd$accounting$full_F_by_link_IF_retained)
    od <- fit$chained$outcome_design
    testthat::expect_false(od$common_A_alias_reduction)
    testthat::expect_equal(od$n_rows, N)
    testthat::expect_identical(od$columns, c("(Intercept)", "x", "z"))
    # Deduplicated cells and pooling groups.
    cells <- nd$cells
    testthat::expect_false(anyDuplicated(paste(cells$cohort, cells$s, cells$t)) > 0L)
    testthat::expect_true(all(nd$fitted_catalog$target_cell %in% cells$cell_id))
    testthat::expect_true(all(c("catalog", "auxiliary") %in% nd$fitted_catalog$role))
    n_groups <- length(nd$groups)
    if (p == "separate") testthat::expect_equal(n_groups, nrow(cells))
    if (p == "within_cohort") {
      testthat::expect_equal(n_groups, length(unique(cells$cohort)))
      testthat::expect_true(all(tapply(cells$cohort, cells$group_id, function(v) length(unique(v))) == 1L))
    }
    if (p == "across_cohorts") testthat::expect_equal(n_groups, 1L)
    testthat::expect_true(all(vapply(nd$groups, function(g) g$rank, integer(1)) == 2L))
    testthat::expect_true(nd$coefficients$has_local_intercepts)
    testthat::expect_length(nd$coefficients$imputation_local_intercepts, nrow(cells))
    # Treatment IPW skips the counterfactual OR; reg skips the treatment logit; DR fits both.
    if (m == "ipw") {
      testthat::expect_null(nd$counterfactual_or)
      testthat::expect_true(all(is.na(nd$fitted_catalog$or_block)))
      testthat::expect_equal(nd$accounting$n_or_fits, 0)
    } else {
      testthat::expect_equal(nd$accounting$n_or_fits, 1)
      testthat::expect_equal(nrow(nd$counterfactual_or$blocks), length(unique(nd$fitted_catalog$or_block)))
      testthat::expect_equal(nd$counterfactual_or$rank, 2L)
    }
    if (m == "reg") {
      testthat::expect_length(nd$treatment, 0L)
      testthat::expect_true(all(is.na(nd$fitted_catalog$treatment_model)))
      testthat::expect_equal(nd$accounting$n_treatment_fits, 0)
    } else {
      testthat::expect_equal(length(nd$treatment), length(unique(nd$fitted_catalog$treatment_model)))
      testthat::expect_gt(length(nd$treatment), 0L)
    }
    # Original-unit full-F IF rows, including off-A and frame-only identities.
    av <- fit$chained$available
    testthat::expect_true(any(av))
    testthat::expect_equal(fit$n, N)
    testthat::expect_identical(rownames(fit$inffunc), fx$frame$id)
    testthat::expect_true(all(fx$frame_only %in% rownames(fit$inffunc)))
    testthat::expect_true(any(fit$inffunc[fx$off_A, av, drop = FALSE] != 0))
    testthat::expect_true(all(is.finite(fit$inffunc[, av, drop = FALSE])))
    testthat::expect_equal(fit$se[av], unname(sqrt(diag(fit$V_analytical)[av] / fit$n)), tolerance = 1e-12)
    # Existing resource reservation for the final diagnostic copy.
    ra <- fit$chained$resource_accounting
    testthat::expect_equal(ra$final_diagnostic_copy_entries, 5 * (4 * nd$accounting$owned_entries + 4096), tolerance = 0)
    testthat::expect_lte(max(ra$simultaneous_entries, ra$initial_envelope_entries) + ra$final_diagnostic_copy_entries,
      fit$chained$public$numeric_workspace_entries)
    # Reporting adapters.
    testthat::expect_true(all(cdid::tidy(fit)$estimator == fit$chained$estimator))
    testthat::expect_identical(cdid::glance(fit)$estimator, fit$chained$estimator)
    txt <- paste(utils::capture.output(summary(fit)), collapse = "\n")
    testthat::expect_match(txt, "pure actual-change imputation", fixed = TRUE)
    testthat::expect_match(txt, "no\\s+observation[- ]probability\\s+model\\s+is\\s+fitted")
    testthat::expect_match(nd$interpretation, "selection_xformla are inactive", fixed = TRUE)
  }
})

testthat::test_that("inactive probability arguments cannot change a pure-imputation fit", {
  testthat::skip_if_not(impp_has_installed_cdid(), "Installed cdid namespace required.")
  fx <- impp_fixture()
  ref <- get0("dr:separate", envir = impp_state, inherits = FALSE)
  if (is.null(ref)) ref <- impp_imputation(fx, "dr", "separate")
  alt <- impp_fit(fx, est_method = "dr", selection = "conditional_mtar", selection_est_method = "imputation",
    selection_model = "independent_period_logit", selection_pooling = "across_cohorts", selection_xformla = ~1)
  for (nm in c("att", "se", "V_analytical", "inffunc")) testthat::expect_identical(alt[[nm]], ref[[nm]])
  testthat::expect_identical(alt$chained$selection$imputation_pooling, "separate")
  testthat::expect_true(is.na(alt$chained$selection$selection_model))
})

testthat::test_that("aggregation, clustering and multiplier bands use the existing consumers on full-F IF rows", {
  testthat::skip_if_not(impp_has_installed_cdid(), "Installed cdid namespace required.")
  fx <- impp_fixture()
  N <- nrow(fx$frame)
  fit <- get0("dr:separate", envir = impp_state, inherits = FALSE)
  if (is.null(fit)) fit <- impp_imputation(fx, "dr", "separate")
  for (tp in c("simple", "group", "dynamic", "calendar")) {
    ag <- cdid::aggte(fit, type = tp)
    testthat::expect_s3_class(ag, "cdid_AGGTEobj")
    testthat::expect_true(is.finite(ag$overall.att) && is.finite(ag$overall.se) && ag$overall.se > 0)
    testthat::expect_identical(ag$chained$estimator, fit$chained$estimator)
  }
  # Clustering changes inference only (no change in GMM point weights or IF rows).
  fit_cl <- impp_imputation(fx, "dr", "separate", clustervars = "cl")
  testthat::expect_identical(fit_cl$att, fit$att)
  testthat::expect_identical(fit_cl$inffunc, fit$inffunc)
  av <- fit$chained$available
  sums <- rowsum(fit$inffunc[, av, drop = FALSE], fx$frame$cl, reorder = FALSE)
  V_cl <- crossprod(sweep(sums, 2L, colMeans(sums), "-")) / N
  testthat::expect_equal(unname(fit_cl$V_analytical[av, av]), unname(V_cl), tolerance = 1e-12)
  testthat::expect_true(fit_cl$chained$inference$clustered)
  # Multiplier draws use the caller RNG stream.
  set.seed(52011L)
  fit_bs <- impp_imputation(fx, "dr", "separate", clustervars = "cl", bstrap = TRUE, cband = TRUE, biters = 64L)
  set.seed(52011L)
  fit_bs2 <- impp_imputation(fx, "dr", "separate", clustervars = "cl", bstrap = TRUE, cband = TRUE, biters = 64L)
  testthat::expect_identical(fit_bs$att, fit$att)
  testthat::expect_identical(fit_bs$se, fit_bs2$se)
  testthat::expect_identical(fit_bs$c, fit_bs2$c)
  testthat::expect_true(is.finite(fit_bs$c) && fit_bs$c > 0)
  ag_bs <- cdid::aggte(fit_bs, type = "dynamic")
  testthat::expect_true(is.finite(ag_bs$overall.att) && is.finite(ag_bs$overall.se))
})

testthat::test_that("NYT pools, universal base period and PT-all reach the same imputation backend", {
  testthat::skip_if_not(impp_has_installed_cdid(), "Installed cdid namespace required.")
  fx <- impp_fixture()
  for (m in impp_methods) {
    fit <- impp_imputation(fx, m, "separate", control_group = "notyettreated", base_period = "universal")
    nd <- fit$chained$nuisance_diagnostics
    testthat::expect_s3_class(fit, "cdid_MP")
    testthat::expect_true(any(grepl(",", nd$fitted_catalog$controls, fixed = TRUE)))
    testthat::expect_identical(fit$DIDparams$control_group, "notyettreated")
    testthat::expect_identical(fit$chained$base_period, "universal")
    testthat::expect_true(any(fit$chained$role == "reference"))
    if (m != "ipw") testthat::expect_true(any(grepl(",", nd$counterfactual_or$blocks$control_cohorts, fixed = TRUE)))
  }
  fit_pt <- impp_imputation(fx, "dr", "separate", pt_assumption = "all", pt_start = 1)
  testthat::expect_identical(fit_pt$chained$pt$pt_assumption, "all")
  testthat::expect_equal(fit_pt$chained$pt$pt_start, 1)
  testthat::expect_identical(fit_pt$chained$nuisance_diagnostics$method, "imputation")
})

# ------------------------------------------------------------------------------
# D. Full-F covariates, frame-only identities and invariances
# ------------------------------------------------------------------------------

testthat::test_that("xformla is evaluated on every F row: frame-only covariates matter only under imputation", {
  testthat::skip_if_not(impp_has_installed_cdid(), "Installed cdid namespace required.")
  fx <- impp_fixture()
  fo <- fx$frame_only[fx$frame$g[match(fx$frame_only, fx$frame$id)] == 3][1L]
  testthat::expect_false(is.na(fo))
  flipped <- fx
  hit <- flipped$frame$id == fo
  flipped$frame$x[hit] <- 1 - flipped$frame$x[hit]
  imp <- get0("dr:separate", envir = impp_state, inherits = FALSE)
  if (is.null(imp)) imp <- impp_imputation(fx, "dr", "separate")
  imp_flip <- impp_imputation(flipped, "dr", "separate")
  testthat::expect_gt(max(abs(imp_flip$att - imp$att), na.rm = TRUE), 0)
  # The baseline weighted route evaluates xformla on repeat observers only.
  base <- impp_fit(fx, est_method = "dr")
  base_flip <- impp_fit(flipped, est_method = "dr")
  testthat::expect_identical(base_flip$att, base$att)
  # Missing covariates on a frame-only row are refused only under imputation.
  missing_x <- fx
  missing_x$frame$x[missing_x$frame$id == fo] <- NA
  testthat::expect_error(impp_imputation(missing_x, "dr", "separate"), class = "cdid_chained_request_covariate_error")
  testthat::expect_identical(impp_fit(missing_x, est_method = "dr")$att, base$att)
  # Unknown frame-only cohorts are refused: repeat rates use every roster unit.
  unknown <- fx
  unknown$frame$g <- NULL
  e <- testthat::expect_error(impp_imputation(unknown, "dr", "separate"), class = "cdid_chained_request_input_error")
  testthat::expect_match(conditionMessage(e), "known cohorts", fixed = TRUE)
})

testthat::test_that("row order, global weight scale and chunk size leave pure-imputation results unchanged", {
  testthat::skip_if_not(impp_has_installed_cdid(), "Installed cdid namespace required.")
  fx <- impp_fixture()
  ref <- get0("dr:within_cohort", envir = impp_state, inherits = FALSE)
  if (is.null(ref)) ref <- impp_imputation(fx, "dr", "within_cohort")
  ord <- c(seq.int(2L, nrow(fx$frame), 2L), seq.int(1L, nrow(fx$frame), 2L))
  shuffled <- fx
  shuffled$frame <- fx$frame[ord, , drop = FALSE]
  shuffled$data <- fx$data[rev(seq_len(nrow(fx$data))), , drop = FALSE]
  s <- impp_imputation(shuffled, "dr", "within_cohort")
  testthat::expect_identical(rownames(s$inffunc), fx$frame$id[ord])
  testthat::expect_equal(s$att, ref$att, tolerance = 1e-10)
  testthat::expect_equal(unname(s$inffunc[fx$frame$id, , drop = FALSE]), unname(ref$inffunc), tolerance = 1e-10)
  # Degree-zero normalization: a common weight scale cancels.
  scaled <- fx
  scaled$frame$w <- 3 * fx$frame$w
  scaled$data$w <- 3 * fx$data$w
  sc <- impp_imputation(scaled, "dr", "within_cohort")
  testthat::expect_equal(sc$att, ref$att, tolerance = 1e-10)
  testthat::expect_equal(unname(sc$inffunc), unname(ref$inffunc), tolerance = 1e-10)
  # An explicit chunk size replaces automatic row planning without changing values.
  ch <- impp_imputation(fx, "dr", "within_cohort", control = list(chunk_rows = 7L))
  testthat::expect_false(ch$chained$nuisance_diagnostics$accounting$automatic_chunk_rows)
  testthat::expect_equal(ch$att, ref$att, tolerance = 1e-10)
  testthat::expect_equal(unname(ch$inffunc), unname(ref$inffunc), tolerance = 1e-10)
})

testthat::test_that("a balanced panel needs no observation logit under imputation", {
  testthat::skip_if_not(impp_has_installed_cdid(), "Installed cdid namespace required.")
  fx <- impp_fixture(balanced = TRUE)
  # The weighted correction would fit an all-success observation logit and refuses.
  testthat::expect_error(impp_fit(fx, est_method = "dr", selection = "conditional_mtar", selection_xformla = ~x),
    class = "cdid_error")
  for (m in impp_methods) {
    fit <- impp_imputation(fx, m, "separate")
    testthat::expect_true(all(fit$chained$available[fit$chained$role == "post"]))
    testthat::expect_equal(fit$chained$nuisance_diagnostics$accounting$observation_logit_models, 0)
  }
})

testthat::test_that("unsupported D5 auxiliary pairs stay unavailable and never reach the imputation backend", {
  testthat::skip_if_not(impp_has_installed_cdid(), "Installed cdid namespace required.")
  fx <- impp_fixture()
  # Cohort 3 never observes date 1, so its (1, 2) pretrend comparison has no pair support.
  drop <- fx$data$g == 3 & fx$data$time == 1
  fx$data$y[drop] <- NA_real_
  fit <- impp_imputation(fx, "dr", "separate")
  nd <- fit$chained$nuisance_diagnostics
  tm <- fit$chained$target_meta
  pre32 <- tm$role == "pre" & tm$g == 3 & tm$time == 2
  testthat::expect_true(any(pre32))
  testthat::expect_false(any(fit$chained$available[pre32]))
  testthat::expect_true(any(grepl("unsupported_pair", tm$support_reason[pre32], fixed = TRUE)))
  testthat::expect_true("unsupported_pair" %in% nd$auxiliary_descriptor_status$status)
  testthat::expect_false(any(nd$cells$cohort == 3 & nd$cells$s == 1))
  testthat::expect_true(all(fit$chained$available[tm$role == "post" & tm$g == 3]))
})

# ------------------------------------------------------------------------------
# E. Formula branches and exact finite identities (IMPUTATION_SPEC 2.4, 8.2)
# ------------------------------------------------------------------------------

testthat::test_that("intercept-only imputation gives DR identical to IPW for the same correction", {
  testthat::skip_if_not(impp_has_installed_cdid(), "Installed cdid namespace required.")
  fx <- impp_fixture()
  ipw <- impp_imputation(fx, "ipw", "separate", xformla = ~1)
  dr <- impp_imputation(fx, "dr", "separate", xformla = ~1)
  nd <- dr$chained$nuisance_diagnostics
  testthat::expect_true(all(vapply(nd$groups, function(g) g$rank, integer(1)) == 0L))
  testthat::expect_equal(nd$counterfactual_or$rank, 0L)
  testthat::expect_identical(dr$chained$outcome_design$columns, "(Intercept)")
  testthat::expect_equal(dr$att, ipw$att, tolerance = 1e-10)
  testthat::expect_equal(unname(dr$inffunc), unname(ipw$inffunc), tolerance = 1e-10)
})

testthat::test_that("no-intercept formulas fit without local intercepts on every method", {
  testthat::skip_if_not(impp_has_installed_cdid(), "Installed cdid namespace required.")
  fx <- impp_fixture()
  for (m in impp_methods) {
    fit <- impp_imputation(fx, m, "within_cohort", xformla = ~0 + x + z)
    nd <- fit$chained$nuisance_diagnostics
    testthat::expect_false(fit$chained$outcome_design$intercept)
    testthat::expect_false(nd$coefficients$has_local_intercepts)
    testthat::expect_length(nd$coefficients$imputation_local_intercepts, 0L)
    testthat::expect_equal(nd$accounting$n_imputation_local_intercepts, 0)
    if (m != "ipw") {
      testthat::expect_length(nd$counterfactual_or$local_block_intercepts, 0L)
      testthat::expect_equal(nd$accounting$n_or_local_intercepts, 0)
    }
    if (m != "reg") testthat::expect_identical(unname(vapply(nd$coefficients$treatment, function(b) names(b)[1L], "")),
      rep("x", length(nd$coefficients$treatment)))
  }
})

testthat::test_that("exact aliases use group-local preprocessing while the treatment logit keeps its rank refusal", {
  testthat::skip_if_not(impp_has_installed_cdid(), "Installed cdid namespace required.")
  fx <- impp_fixture()
  fx$frame$x2 <- 2 * fx$frame$x
  fx$data$x2 <- 2 * fx$data$x
  reg <- impp_imputation(fx, "reg", "separate", xformla = ~x + x2 + z)
  nd <- reg$chained$nuisance_diagnostics
  testthat::expect_identical(reg$chained$outcome_design$columns, c("(Intercept)", "x", "x2", "z"))
  for (g in nd$groups) {
    testthat::expect_equal(g$rank, 2L)
    testthat::expect_length(g$aliased_columns, 1L)
    testthat::expect_true(g$aliased_columns %in% c("x", "x2"))
  }
  testthat::expect_length(nd$counterfactual_or$aliased_columns, 1L)
  testthat::expect_error(impp_imputation(fx, "ipw", "separate", xformla = ~x + x2 + z), class = "cdid_cp04_rank_error")
})

testthat::test_that("a single never-treated control pool makes the pooled imputation and counterfactual OR coincide", {
  testthat::skip_if_not(impp_has_installed_cdid(), "Installed cdid namespace required.")
  fx <- impp_fixture()
  for (p in c("within_cohort", "across_cohorts")) {
    fit <- get0(paste("reg", p, sep = ":"), envir = impp_state, inherits = FALSE)
    if (is.null(fit)) fit <- impp_imputation(fx, "reg", p)
    nd <- fit$chained$nuisance_diagnostics
    testthat::expect_true(all(nd$counterfactual_or$blocks$control_cohorts == "0"))
    nt_group <- Filter(function(g) all(is.infinite(g$cohorts)) || p == "across_cohorts", nd$groups)
    testthat::expect_length(nt_group, 1L)
    testthat::expect_equal(nd$coefficients$shared_slopes, nt_group[[1L]]$slopes, tolerance = 1e-10)
    blocks <- nd$counterfactual_or$blocks
    nt_cells <- nd$cells[is.infinite(nd$cells$cohort), , drop = FALSE]
    hit <- match(paste(blocks$s, blocks$t), paste(nt_cells$s, nt_cells$t))
    testthat::expect_false(anyNA(hit))
    testthat::expect_equal(unname(nd$counterfactual_or$local_block_intercepts), nt_cells$local_intercept[hit],
      tolerance = 1e-10)
  }
})


# Consumer smoke/self-consistency only: the independent public oracle is identity-GMM.
# No independent truth for estimated weighting or bootstrap is asserted here.
testthat::test_that("default two-step and explicit alias retain the imputation consumers", {
  testthat::skip_if_not(impp_has_installed_cdid(), "Installed cdid namespace required.")
  fx <- impp_fixture()
  # NULL removes the helper's identity override, exposing the public default.
  def <- impp_imputation(fx, "dr", "separate", gmm_weighting = NULL)
  alias <- impp_imputation(fx, "dr", "separate", gmm_weighting = "two_step",
    gmm_covariance = "tikhonov")
  for (nm in c("att", "se", "V_analytical", "inffunc"))
    testthat::expect_identical(alias[[nm]], def[[nm]])
  testthat::expect_identical(def$chained$request$gmm_weighting, "optimal")
  testthat::expect_identical(alias$chained$request$gmm_weighting_requested, "two_step")
  handling <- def$chained$covariance_handling
  testthat::expect_identical(handling$weighting_canonical, "optimal")
  testthat::expect_identical(handling$handler_selected, "tikhonov")
  testthat::expect_identical(alias$chained$covariance_handling$handler_invoked, handling$handler_invoked)
  testthat::expect_identical(alias$chained$covariance_handling$lambda, handling$lambda)
  testthat::expect_equal(def$chained$reduction_summary$n_links_all,
    def$chained$reduction_summary$n_links_used)
  testthat::expect_identical(rownames(def$inffunc), fx$frame$id)
  testthat::expect_true(any(def$chained$available))
  testthat::expect_true(all(is.finite(def$inffunc[, def$chained$available, drop = FALSE])))
  testthat::expect_identical(def$chained$nuisance_diagnostics$method, "imputation")
})
